function is_ollama_too_many_request_error(post) {
  const ollama_too_many_request_error = "The service is receiving too many requests from you"
  if (post.ai_validation.raw_ai_output && post.ai_validation.raw_ai_output.error && post.ai_validation.raw_ai_output.error === ollama_too_many_request_error) {
    return true
  }
}
function is_ollama_error(post) {
  if (post.ai_validation.raw_ai_output && post.ai_validation.raw_ai_output.error) {
    return true
  }
}


const src = $input.first()
const ai_posts = src.json.data
const signals = []
const not_signals = []
const errors = []
const ollama_too_many_requests = []


for (const post of ai_posts) {
  if (post.classification.is_signal) {
    signals.push(post)
  } else if (is_ollama_too_many_request_error(post)) {
    ollama_too_many_requests.push(post)
  } else if (is_ollama_error(post)) {
    errors.push(post)
  } else {
    not_signals.push(post)
  }
}

return {
  signals,
  not_signals,
  errors,
  ollama_too_many_requests,
}
