const spamWords = [
  'vip', 'referral', 'subscribe', 'promo', 'sponsored', 'advertisement'
];
function hasAny(text, words) {
  return words.some(word => text.includes(word));
}

function filter_content_len(post) {
  if (post.content.length < 9) return false
  return true
}
function filter_spam(post) {
  if (hasAny(post.content, spamWords)) return false
  return true
}

const inputItems = $input.all()
