const items = $input.first();

let wins = 0;
let losses = 0;
let unclear = 0;

const results = [];

for (const item of items.json.data) {
  const r = item;
  results.push(r);

  if (r.outcome === 'win') wins++;
  else if (r.outcome === 'loss') losses++;
  else unclear++;
}

const considered = wins + losses;
const winrate = considered > 0 ? Number(((wins / considered) * 100).toFixed(2)) : null;

return [{
  json: {
    summary: {
      total_signals: items.length,
      wins,
      losses,
      unclear,
      considered,
      winrate,
    },
    results,
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
function sort_posts(a, b) {
  if (a.json.date > b.json.date) return 1
  if (b.json.date > a.json.date) return -1
  return 0
}

let context_arr = []
const items = $input.all().sort(sort_posts)

for (const item of items) {
  item.json.context = context_arr.join('\n');
  context_arr.push(item.json.content)
  if (context_arr.length >= 4) {
    context_arr.shift()
  }
}

return items;

