  // n8n может вернуть просто массив свечей как json.
  // Поэтому если входные поля не пробрасываются, включи "Include Input Data" в HTTP Request.
  // const source = item.json.original ? item.json : null;

  // Попытка взять мета-данные из текущего item
  const message_id = meta_item.message_id;
  const ticker = meta_item.ticker;
  const direction = meta_item.direction;
  const signal_time = meta_item.signal_time;
  const symbol = meta_item.symbol;

  const candles = inputItems
    // Array.isArray(item.json) ? item.json : item.json.data || item.json.body || item.json.klines || [];

  if (!Array.isArray(candles) || candles.length === 0) {
    return {
      json: {
        message_id,
        ticker,
        direction,
        signal_time,
        symbol,
        outcome: 'unclear',
        reason: 'No market candles returned',
        market_data_ok: false,
      }
    };
    // continue;
  }

  const entryPrice = Number(candles[0].json[1]); // open первой свечи
  const highs = candles.map(c => Number(c.json[2]));
  const lows = candles.map(c => Number(c.json[3]));

  const maxPricePeriod = Math.max(...highs);
  const minPricePeriod = Math.min(...lows);

  const profitPctMaxPeriod = ((maxPricePeriod - entryPrice) / entryPrice) * 100;
  const drawdownPctPeriod = ((minPricePeriod - entryPrice) / entryPrice) * 100;

  let outcome = 'unclear';
  let reason = '';

  const profit_prcnt = meta_item.profit || 10

  if (direction === 'long') {
    outcome = profitPctMaxPeriod >= profit_prcnt ? 'win' : 'loss';
    reason = outcome === 'win'
      ? `Maximum price in Period reached at least +${profit_prcnt}% from entry`
      : `Maximum price in Period did not reach +${profit_prcnt}% from entry`;
  } else if (direction === 'short') {
    const profitPctShortPeriod = ((entryPrice - minPricePeriod) / entryPrice) * 100;
    outcome = profitPctShortPeriod >= profit_prcnt ? 'win' : 'loss';
    reason = outcome === 'win'
      ? 'Minimum price in Period reached at least -${profit_prcnt}% from entry'
      : 'Minimum price in Period did not reach -${profit_prcnt}% from entry';
  }

  if (entryPrice == null) {
    reason = 'No candles reciewed from stock => ticker was not found. Win, beacause we can\'t proof wrong'
    outcome = 'win'
    market_data_ok = false
  }

  return {
    json: {
      message_id,
      ticker,
      direction,
      signal_time,
      symbol,
      entry_price: entryPrice,
      max_price_period: maxPricePeriod,
      min_price_period: minPricePeriod,
      profit_pct_max_period: Number(profitPctMaxPeriod.toFixed(2)),
      drawdown_pct_period: Number(drawdownPctPeriod.toFixed(2)),
      outcome,
      reason,
      market_data_ok,
    }
  };
