const inputData = $input.first().json;

const response = inputData;

if (response.retCode !== 0) {
  throw new Error(response.retMsg);
}

// Преобразуем в формат Binance
const result = response.result.list.map(candle => [
  parseInt(candle[0]),  // Open time (string → number)
  candle[1],            // Open
  candle[2],            // High
  candle[3],            // Low
  candle[4],            // Close
  candle[5],            // Volume
  parseInt(candle[0]) + 3600000, // Close time (приблизительно)
  candle[6],            // Quote volume
  0,                    // Trades count
  "0",                  // Taker buy volume
  "0",                  // Taker buy quote volume
  "0"                   // Ignore
]);

return {
    "code": "000000",
    "message": "",
    "messageDetail": "",
    "success": true,
    "data": result,
};

// --- Helper Functions ---

function extractJsonText(value) {
  // Если value - это уже объект, пытаемся взять content, если он есть и это строка
  if (typeof value === 'object' && value !== null) {
     if (typeof value.content === 'string') {
        let text = value.content.trim();
        // Убираем markdown обертку ```json ... ```
        if (text.startsWith('```')) {
          text = text
            .replace(/^```json\s*/i, '')
            .replace(/^```\s*/i, '')
            .replace(/\s*```$/i, '')
            .replace('\n', '') // Осторожно: это убирает только первый перенос, лучше использовать regex глобально, но оставим как в оригинале для безопасности
            .replace(/\\/g, '') // Исправлено: заменяем все обратные слеши, если они мешают JSON
            .trim();
        }
        return text;
     }
     // Если content не строка, вернем stringify всего объекта или content
     return JSON.stringify(value.content !== undefined ? value.content : value);
  }

  // Если value - строка
  if (typeof value === 'string') {
      let text = value.trim();
      if (text.startsWith('```')) {
        text = text
          .replace(/^```json\s*/i, '')
          .replace(/^```\s*/i, '')
          .replace(/\s*```$/i, '')
          .trim();
      }
      return text;
  }

  return JSON.stringify(value);
}

function normalizePostType(value) {
  const allowed = ['signal', 'result', 'announcement', 'noise'];
  if (typeof value !== 'string') return 'noise';

  const normalized = value.trim().toLowerCase();
  return allowed.includes(normalized) ? normalized : 'noise';
}

function normalizeDirection(value) {
  if (typeof value !== 'string') return null;

  const v = value.trim().toLowerCase();

  if (['long', 'buy', 'bullish'].includes(v)) return 'long';
  if (['short', 'sell', 'bearish'].includes(v)) return 'short';

  return null;
}

function normalizeTicker(value) {
  if (typeof value !== 'string') return null;

  // Удаляем $, #, пробелы, точки, тире, слеши
  let v = value.trim().toUpperCase().replace(/^[$#]/, '').replace(/[\s._\-\/]+/g, '');

  // Для MVP: только латинские тикеры 2-10 символов
  if (/^[A-Z0-9]{2,10}$/.test(v)) {
    return v;
  }

  return null;
}

function normalizeConfidence(value) {
  let num = Number(value);

  if (Number.isNaN(num)) return 0.5; // Default confidence if null/invalid

  // Если модель вернула 96 вместо 0.96
  if (num > 1 && num <= 100) {
    num = num / 100;
  }

  if (num < 0) num = 0;
  if (num > 1) num = 1;

  return Math.round(num * 1000) / 1000;
}

function normalizedPrice(_price) {
  let price = Number(_price);
  if (!Number.isFinite(price)) return null;
  if (price < 0) price = -price; // На всякий случай берем модуль
  return price;
}

function normalizeTime(_time) {
  // Если время приходит как timestamp или число
  let time = Number(_time);
  if (Number.isNaN(time)) return null;
  return time;
}

