// 1. Получаем сырые данные из указанной ноды
// В n8n Code Node доступ к предыдущим нодам осуществляется через $input или $node, 
// но так как вы указали конкретный путь, используем его.
// Примечание: В новом Code Node v2 синтаксис может отличаться, но этот должен работать в Function Item/Code legacy.
const rawOutput = $item("0").$node["AI Agent"].json["output"];

let itemsToProcess = [];

// Проверяем, является ли output массивом. 
// Судя по вашему примеру, там приходит список объектов.
if (Array.isArray(rawOutput)) {
  itemsToProcess = rawOutput;
} else if (rawOutput && typeof rawOutput === 'object') {
  // Если пришел один объект, оборачиваем в массив
  itemsToProcess = [rawOutput];
} else {
  // Если ничего нет или ошибка
  return [{ json: { error: "No valid output from AI Agent" } }];
}

const results = [];

for (const src of itemsToProcess) {

  let parsed;
  let parseError = null;
  let rawAiOutputForLog = src; // Сохраняем оригинал для лога

  try {
    // Пытаемся извлечь JSON текст. 
    // Так как src уже выглядит как объект (parsed JSON от AI агента), 
    // extractJsonText вернет либо строку content, либо stringify объекта.
    // Но скорее всего, нам нужно работать напрямую с полями объекта src, 
    // так как AI Agent уже вернул JSON object.

    // ВАЖНО: Если $node["AI Agent"].json["output"] уже содержит JS Object (что обычно и бывает в n8n),
    // то JSON.parse делать не нужно. Нужно просто проверить структуру.

    // Однако, ваш исходный код предполагал, что там может быть строка с ```json```.
    // Давайте проверим тип.

    if (typeof src === 'string') {
       // Если это строка, пробуем распарсить
       const jsonText = extractJsonText(src);
       parsed = JSON.parse(jsonText);
    } else {
       // Если это объект, считаем, что он уже распарсен
       parsed = src;
    }

  } catch (error) {
    parseError = error.message;
    parsed = null;
  }

  // Fallback, если не удалось получить валидный объект
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    results.push({
      json: {
        ai_validation: {
          validated: false,
          error_stage: 'json_parse',
          error_message: parseError || 'AI output is not a valid JSON object',
          raw_ai_output: JSON.stringify(rawAiOutputForLog).substring(0, 500), // Обрезаем для безопасности
        },
        classification: {
          message_id: null,
          post_type: 'noise',
          is_signal: false,
          date: null,
          ticker: null,
          direction: null,
          confidence: 0,
          profit: null,
          entry_point: null,
          close_point: null,
          profit_point: null,
          time: null,
          reason: 'Fallback: invalid AI JSON',
        },
      },
    });
    continue; // Переходим к следующему элементу
  }

  // Нормализация полей
  const postType = normalizePostType(parsed.category); // В вашем примере поле называется category
  const direction = normalizeDirection(parsed.direction);
  const ticker = normalizeTicker(parsed.ticker);
  const confidence = normalizeConfidence(parsed.confidence);

  const date = parsed.date ? parsed.date : null;
  const profit = normalizedPrice(parsed.profit);
  const entry_point = normalizedPrice(parsed.entry_point);
  const close_point = normalizedPrice(parsed.stop_point); // Маппинг stop_point -> close_point (как стоп)
  const profit_point = normalizedPrice(parsed.profit_point); // Первый тейк
  const time = normalizeTime(parsed.time);

  const isSignalBool = typeof parsed.is_signal === 'boolean' ? parsed.is_signal : (postType === 'signal');

  const reason = typeof parsed.reason === 'string' && parsed.reason.trim()
    ? parsed.reason.trim()
    : 'No reason provided';

  const messageId = parsed.message_id ?? null;

  // Логическая коррекция
  const finalTicker = postType === 'signal' ? ticker : null;
  const finalDirection = postType === 'signal' ? direction : null;
  const finalIsSignal = (postType === 'signal' && isSignalBool);

  const validationWarnings = [];

  // Сравнение оригинала и нормализованного значения для отладки
  if (parsed.category && parsed.category.toLowerCase() !== postType) {
    validationWarnings.push(`category normalized: ${parsed.category} -> ${postType}`);
  }
  if (parsed.direction && parsed.direction.toLowerCase() !== finalDirection) {
    validationWarnings.push(`direction normalized: ${parsed.direction} -> ${finalDirection}`);
  }
  if (parsed.ticker && parsed.ticker.toUpperCase().replace(/[^A-Z0-9]/g,'') !== finalTicker) {
    validationWarnings.push(`ticker normalized: ${parsed.ticker} -> ${finalTicker}`);
  }

  // Формируем итоговый объект
  results.push({
    json: {
      // Можно добавить исходные данные, если нужно
      // ...src, 
      ai_validation: {
        validated: true,
        warnings: validationWarnings.length > 0 ? validationWarnings : null,
        // raw_ai_output можно убрать, если оно занимает много места, или оставить краткую версию
      },
      classification: {
        message_id: messageId,
        post_type: postType,
        is_signal: finalIsSignal,
        date: date,
        ticker: finalTicker,
        direction: finalDirection,
        confidence: confidence,
        reason: reason,
        // Финансовые данные
        profit: profit,
        entry_point: entry_point,
        close_point: close_point, // Это Stop Loss
        profit_point: profit_point, // Это Take Profit 1
        time: time
      },
    },
  });
}

return results;

