// Функция проверки приблизительного равенства с погрешностью 0.5%
function pribliz(a, b, proc) {
  const min = b - (b / 100 * proc);
  const max = b + (b / 100 * proc);
  return a > min && a < max;
}

// Получаем данные сигнала из предыдущего узла n8n
const signal = $('Формирование метаданных запроса4').first().json

// Получаем свечи (массив из HTTP запроса к Binance)
const candles = $input.all().map(item => item.json);

let startSignal = false;
let result = null;
let entryPrice = null; // Добавляем переменную для хранения цены входа

// Проходим по всем свечам
for (const candle of candles) {
  const price = parseFloat(candle[1]); // Цена закрытия свечи

  // Проверяем вход в позицию
  if (!startSignal) {
    if (pribliz(price, parseFloat(signal.entry_point), 0.5)) {
      startSignal = true;
      entryPrice = price; // Запоминаем цену фактического входа
    }
    continue; // Пропускаем проверку стопа, пока не вошли
  }

  // Активная позиция - проверяем стоп и тейк-профит
  if (signal.direction === "long") {
    if (price <= parseFloat(signal.stop_point)) {
      const percentChange = ((signal.stop_point - entryPrice) / entryPrice) * 100;
      result = {
        status: "stop_loss",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `❌ Сработал стоп-лосс (${percentChange.toFixed(2)}%)`
      };
      break;
    }
    if (price >= parseFloat(signal.profit_point)) {
      const percentChange = ((signal.profit_point - entryPrice) / entryPrice) * 100;
      result = {
        status: "take_profit",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `✅ Сработал тейк-профит (+${percentChange.toFixed(2)}%)`
      };
      break;
    }
  } 
  else if (signal.direction === "short") {
    if (price >= parseFloat(signal.stop_point)) {
      const percentChange = ((entryPrice - signal.stop_point) / entryPrice) * 100;
      result = {
        status: "stop_loss",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `❌ Сработал стоп-лосс (-${percentChange.toFixed(2)}%)`
      };
      break;
    }
    if (price <= parseFloat(signal.profit_point)) {
      const percentChange = ((entryPrice - signal.profit_point) / entryPrice) * 100;
      result = {
        status: "take_profit",
        exit_price: price,
        percent: percentChange.toFixed(2),
        message: `✅ Сработал тейк-профит (+${percentChange.toFixed(2)}%)`
      };
      break;
    }
  }
}

// Если ни стоп, ни профит не сработали за период
if (!result) {
  result = {
    status: "no_exit",
    exit_price: null,
    percent: null,
    message: "⏸️ Не сработало ни стопа, ни профита за неделю"
  };
}

// Возвращаем результат с исходными данными сигнала
