function parseAIJson(input) {
    // Очищаем строку от markdown
    let clean = String(input)
        .replace(/^```json\s*/, '')
        .replace(/```\s*$/, '')
        .trim();

    // Находим JSON часть
    const match = clean.match(/(\[\s*\{[\s\S]*\}\s*\]|\{\s*[\s\S]*\})/);
    if (!match) {
        throw new Error('No JSON found');
    }

    // Парсим
    return match[0];
}

