  if (a.json.date > b.json.date) return 1
  if (b.json.date > a.json.date) return -1
  return 0
}

let context_arr = []
const items = $input.all().sort(sort_posts)

for (const item of items) {
  item.json.context = context_arr.join('\n');
  context_arr.push(item.json.content)
  if (context_arr.length >= 4) {
    context_arr.shift()
  }
}

return items;

