const meta_item = $('Формирование метаданных запроса').first().json;
let market_data_ok = true;

function is_close(point, to_point) {
  const epsilon = to_point * 0.05;
  const delta = to_point - point;
  return Math.abs(delta) < epsilon;
}

// Берём первый (и обычно единственный) item из входа
const currentItem = inputItems;
console.log(currentItem)

// Метаданные сигнала
const message_id = meta_item.message_id;
const ticker = meta_item.ticker;
const direction = meta_item.direction;
const signal_time = meta_item.signal_time;
const symbol = meta_item.symbol;
const entry_point = Number(meta_item.entry_point);
const close_point = Number(meta_item.close_point);
const profit_point = Number(meta_item.profit_point);

// === ИЗВЛЕЧЕНИЕ СВЕЧЕЙ ИЗ НОВОГО ФОРМАТА ===
const candles = currentItem.json || [];
console.log(candles)

if (!Array.isArray(candles) || candles.length === 0) {
  return {
    json: {
      message_id,
      ticker,
      direction,
      signal_time,
      symbol,
      outcome: 'unclear',
      reason: 'No market candles returned',
      market_data_ok: false,
    }
  };
}

// Первая свеча = точка входа (по открытию)
const entryPrice = Number(candles[0][1]);

let outcome = 'unclear';
let reason = '';

let is_reach_open_point = false;
let is_reach_stop_point = false;
let is_reach_profit_point = false;

// Проверяем, совпадает ли цена открытия с ожидаемой точкой входа
if (is_close(entryPrice, entry_point)) {
  is_reach_open_point = true;
}

// Проходим по всем свечам периода
for (const candle of candles) {
  const high = Number(candle[2]); // Исправлено: было heigh
  const low = Number(candle[3]);

  if (direction === 'long') {
    // Для лонга: проверяем достижение точки входа по максимуму свечи
    if (!is_reach_open_point && high >= entry_point) {
      is_reach_open_point = true;
    }

    // Если вход подтверждён — проверяем стоп и тейк
    if (is_reach_open_point) {
      if (low < close_point) {
        outcome = 'loss';
        reason = 'Price reached STOP point';
        is_reach_stop_point = true;
        break;
      }
      if (high >= profit_point) {
        outcome = 'win';
        reason = 'Price reached PROFIT point without reaching STOP point';
        is_reach_profit_point = true;
        break;
      }
    }
  } 
  else if (direction === 'short') {
    // Для шорта: вход по минимуму свечи
    if (!is_reach_open_point && low <= entry_point) {
      is_reach_open_point = true;
    }

    if (is_reach_open_point) {
      if (high > close_point) {
        outcome = 'loss';
        reason = 'Price reached STOP point';
        is_reach_stop_point = true;
        break;
      }
      if (low <= profit_point) {
        outcome = 'win';
        reason = 'Price reached PROFIT point without reaching STOP point';
        is_reach_profit_point = true;
        break;
      }
    }
  }
}

// Если ни стоп, ни тейк не сработали — считаем сделку убыточной
if (!is_reach_profit_point && !is_reach_stop_point) {
  outcome = 'loss';
  reason = "Price didn't reach STOP or PROFIT point";
}

// Фолбэк: если не удалось получить цену входа
if (entryPrice == null || isNaN(entryPrice)) {
  reason = 'No candles received from stock => ticker was not found. Win, because we can\'t proof wrong';
  outcome = 'win';
  market_data_ok = false;
}

return {
  json: {
    message_id,
    ticker,
    direction,
    signal_time,
    symbol,
    entry_price: entryPrice,
    outcome,
    reason,
    market_data_ok,
  }
};

